/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_listen_ena (Can_IO_Base can_io_base)
{
  can_io_base [CANMOD] |=  (0x02) ; 
}

/*==========================================================================*/

void can_listen_dis (Can_IO_Base can_io_base)
{
  can_io_base [CANMOD] &=  ~(0x02) ; 
}
